import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tag, Plus, Trash2, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";

interface Props {
  siteId: string;
}

export default function LocationMasterView({ siteId }: Props) {
  const [open, setOpen] = useState(false);
  const [rows, setRows] = useState<{ id: string; code: string; sort_order: number }[]>([]);
  const [loading, setLoading] = useState(false);
  const [newCode, setNewCode] = useState("");
  const [busy, setBusy] = useState(false);

  const load = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("site_locations")
      .select("id, code, sort_order")
      .eq("site_id", siteId)
      .order("sort_order");
    if (error) { setLoading(false); toast.error(error.message); return; }
    setRows(data ?? []);
    setLoading(false);
  };

  useEffect(() => {
    if (open) load();
  }, [open, siteId]);

  const add = async (e: React.FormEvent) => {
    e.preventDefault();
    const code = newCode.trim().toUpperCase();
    if (!code) return;
    setBusy(true);
    const nextOrder = (rows[rows.length - 1]?.sort_order ?? 0) + 1;
    const { error } = await supabase
      .from("site_locations")
      .insert({ site_id: siteId, code, sort_order: nextOrder });
    setBusy(false);
    if (error) return toast.error(error.message);
    toast.success(`Location tag ${code} added`);
    setNewCode("");
    load();
  };

  const del = async (id: string, code: string) => {
    if (!confirm(`Delete location "${code}"?`)) return;
    const { error } = await supabase.from("site_locations").delete().eq("id", id).eq("site_id", siteId).select("id").single();
    if (error) return toast.error(error.message);
    toast.success("Location deleted");
    load();
  };

  return (
    <div className="rounded-md border border-border/60 bg-muted/20">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="w-full px-2.5 py-1.5 text-left text-[11px] font-medium flex items-center justify-between gap-2"
      >
        <span className="flex items-center gap-1.5 text-foreground font-semibold">
          <Tag className="h-3 w-3 text-primary" />
          Location Tags ({rows.length || "0"})
        </span>
        <span className="text-[10px] text-muted-foreground">{open ? "Hide" : "Manage"}</span>
      </button>
      {open && (
        <div className="px-2.5 pb-2.5 space-y-2 border-t border-border/50 pt-2">
          {loading ? (
            <div className="flex justify-center py-2">
              <Loader2 className="h-3.5 w-3.5 animate-spin text-muted-foreground" />
            </div>
          ) : (
            <div className="flex flex-wrap gap-1">
              {rows.length === 0 && (
                <p className="text-[10px] text-muted-foreground py-0.5">No location tags configured.</p>
              )}
              {rows.map((r) => (
                <span
                  key={r.id}
                  className="inline-flex items-center gap-1 rounded bg-background border border-border/80 px-1.5 py-0.5 text-[10px] font-mono font-medium shadow-2xs"
                >
                  {r.code}
                  <button
                    onClick={() => del(r.id, r.code)}
                    className="text-muted-foreground hover:text-destructive transition-colors ml-0.5"
                    aria-label={`Delete ${r.code}`}
                  >
                    <Trash2 className="h-2.5 w-2.5" />
                  </button>
                </span>
              ))}
            </div>
          )}
          <form onSubmit={add} className="flex gap-1 pt-0.5">
            <Input
              value={newCode}
              onChange={(e) => setNewCode(e.target.value)}
              placeholder="e.g. WTG-01, BAY-2"
              className="h-7 text-xs rounded-md uppercase"
            />
            <Button type="submit" size="sm" className="h-7 px-2.5 rounded-md" disabled={busy}>
              {busy ? <Loader2 className="h-3 w-3 animate-spin" /> : <Plus className="h-3 w-3" />}
            </Button>
          </form>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import {
  Building2,
  Clock,
  Loader2,
  LogOut,
  CheckCircle,
  XCircle,
  RefreshCw,
  Send,
  ShieldAlert,
} from "lucide-react";
import { toast } from "sonner";
import { Site, AccessRequestRow as Req } from "@/types";
import { formatDateDDMMYYYY } from "@/lib/wasteTypes";
import { Badge } from "@/components/ui/badge";

export default function RequestSiteAccess({ onApproved }: { onApproved: () => void }) {
  const { user, signOut } = useAuth();
  const [sites, setSites] = useState<Site[]>([]);
  const [reqs, setReqs] = useState<Req[]>([]);
  const [loading, setLoading] = useState(true);
  const [siteId, setSiteId] = useState<string>("");
  const [note, setNote] = useState("");
  const [busy, setBusy] = useState(false);

  const load = async () => {
    if (!user) return;
    setLoading(true);
    const [{ data: s }, { data: r }] = await Promise.all([
      supabase.from("sites").select("id, name, location").is("archived_at", null).order("name"),
      supabase
        .from("site_access_requests")
        .select("id, site_id, status, note, created_at")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false }),
    ]);
    setSites(s ?? []);
    setReqs((r ?? []) as Req[]);
    setLoading(false);

    // If approved, hand off
    if ((r ?? []).some((x) => x.status === "approved")) {
      onApproved();
    }
  };

  useEffect(() => {
    load();
  }, [user]);

  const submit = async () => {
    if (!siteId || !user) return;
    setBusy(true);
    const { error } = await supabase.from("site_access_requests").insert({
      user_id: user.id,
      site_id: siteId,
      note: note.trim() || null,
      status: "pending",
    });
    setBusy(false);
    if (error) {
      if (error.code === "23505") toast.error("You've already requested access for this site");
      else toast.error(error.message);
      return;
    }
    toast.success("Access request submitted — it is available in the site administrator’s request list");
    setSiteId("");
    setNote("");
    load();
  };

  const cancel = async (id: string) => {
    const { error } = await supabase.from("site_access_requests").delete().eq("id", id).select("id").single();
    if (error) return toast.error(error.message);
    toast.success("Request cancelled");
    load();
  };

  const requestedIds = new Set(reqs.filter((r) => r.status !== "rejected").map((r) => r.site_id));
  const availableSites = sites.filter((s) => !requestedIds.has(s.id));
  const pending = reqs.filter((r) => r.status === "pending");
  const decided = reqs.filter((r) => r.status !== "pending");

  return (
    <div className="min-h-screen bg-gradient-to-b from-background via-background to-secondary/30 px-4 py-12">
      <div className="max-w-md mx-auto space-y-4">
        {/* Header card */}
        <Card className="rounded-2xl border border-border/80 shadow-md bg-card/95 backdrop-blur-xs">
          <CardContent className="p-6 text-center space-y-2">
            <div className="inline-flex items-center justify-center h-12 w-12 rounded-2xl bg-primary text-primary-foreground shadow-md shadow-primary/25 mb-1">
              <Building2 className="h-6 w-6" />
            </div>
            <h1 className="text-xl font-bold tracking-tight text-foreground">Facility Access Request</h1>
            <p className="text-xs font-semibold text-primary">{user?.email}</p>
            <p className="text-xs text-muted-foreground leading-relaxed">
              Your account requires site administrator authorization before you can view or record hazardous waste logs.
            </p>
          </CardContent>
        </Card>

        {loading ? (
          <div className="flex justify-center py-10">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
          </div>
        ) : (
          <>
            {availableSites.length > 0 && (
              <Card className="rounded-xl border border-border/80 shadow-xs">
                <CardContent className="p-4 sm:p-5 space-y-3.5">
                  <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground flex items-center gap-1.5">
                    <Send className="h-3.5 w-3.5 text-primary" /> Request Access to Facility
                  </h2>
                  <div className="space-y-1.5">
                    <Label className="text-xs font-semibold">Select Facility Site</Label>
                    <Select value={siteId} onValueChange={setSiteId}>
                      <SelectTrigger className="h-9 text-xs rounded-lg">
                        <SelectValue placeholder="Choose a facility site" />
                      </SelectTrigger>
                      <SelectContent>
                        {availableSites.map((s) => (
                          <SelectItem key={s.id} value={s.id}>
                            {s.name} {s.location ? `(${s.location})` : ""}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-xs font-semibold">Reason / Technician Note (optional)</Label>
                    <Textarea
                      value={note}
                      onChange={(e) => setNote(e.target.value)}
                      maxLength={300}
                      rows={2}
                      placeholder="e.g., Assigned to turbine maintenance PM crew..."
                      className="text-xs rounded-lg resize-none"
                    />
                  </div>
                  <Button
                    className="w-full h-9 text-xs font-semibold bg-primary hover:bg-primary/90 text-primary-foreground shadow-sm rounded-lg"
                    disabled={!siteId || busy}
                    onClick={submit}
                  >
                    {busy && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
                    Submit Access Request
                  </Button>
                </CardContent>
              </Card>
            )}

            {pending.length > 0 && (
              <Card className="rounded-xl border border-amber-500/40 bg-amber-500/[0.02] shadow-xs">
                <CardContent className="p-4 space-y-3">
                  <div className="flex items-center justify-between">
                    <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground flex items-center gap-1.5">
                      <Clock className="h-3.5 w-3.5 text-amber-500" /> Pending Approval ({pending.length})
                    </h2>
                  </div>
                  <ul className="divide-y divide-border/60">
                    {pending.map((r) => {
                      const s = sites.find((x) => x.id === r.site_id);
                      return (
                        <li key={r.id} className="py-2.5 flex items-center justify-between gap-2 first:pt-1 last:pb-1">
                          <div className="min-w-0">
                            <p className="text-xs font-semibold text-foreground truncate">{s?.name ?? r.site_id}</p>
                            <p className="text-[11px] text-muted-foreground">
                              Requested {formatDateDDMMYYYY(r.created_at)}
                            </p>
                          </div>
                          <Button
                            size="sm"
                            variant="ghost"
                            className="h-7 text-xs text-muted-foreground hover:text-destructive rounded-lg"
                            onClick={() => cancel(r.id)}
                          >
                            Cancel
                          </Button>
                        </li>
                      );
                    })}
                  </ul>
                </CardContent>
              </Card>
            )}

            {decided.length > 0 && (
              <Card className="rounded-xl border border-border/80 shadow-xs">
                <CardContent className="p-4 space-y-2.5">
                  <h2 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                    Request History
                  </h2>
                  <ul className="divide-y divide-border/60">
                    {decided.map((r) => {
                      const s = sites.find((x) => x.id === r.site_id);
                      const ok = r.status === "approved";
                      return (
                        <li key={r.id} className="py-2.5 flex items-center justify-between gap-2 first:pt-1 last:pb-1">
                          <div className="min-w-0">
                            <p className="text-xs font-semibold text-foreground truncate">{s?.name ?? r.site_id}</p>
                            <p className="text-[11px] text-muted-foreground capitalize">
                              {r.status} {r.note ? `— "${r.note}"` : ""}
                            </p>
                          </div>
                          {ok ? (
                            <Badge variant="success" className="text-[10px]">
                              Approved
                            </Badge>
                          ) : (
                            <Badge variant="destructive" className="text-[10px]">
                              Rejected
                            </Badge>
                          )}
                        </li>
                      );
                    })}
                  </ul>
                </CardContent>
              </Card>
            )}

            <div className="flex gap-2 pt-1">
              <Button
                variant="outline"
                size="sm"
                className="flex-1 h-9 text-xs gap-1.5 rounded-lg"
                onClick={load}
              >
                <RefreshCw className="h-3.5 w-3.5" /> Check Status
              </Button>
              <Button
                variant="outline"
                size="sm"
                className="flex-1 h-9 text-xs gap-1.5 text-destructive hover:bg-destructive/10 rounded-lg"
                onClick={signOut}
              >
                <LogOut className="h-3.5 w-3.5" /> Sign Out
              </Button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import { Calendar as CalendarIcon, FileSpreadsheet, FileText, Download, Tag, FileCheck } from "lucide-react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { WasteEntry, DisposalBatch, fmtNum, WASTE_TYPES, formatDateDDMMYYYY, getMeasureUnit } from "@/lib/wasteTypes";
import { format } from "date-fns";
import { Badge } from "@/components/ui/badge";
import MultiSelect from "./MultiSelect";

type PeriodKind = "all" | "month" | "range" | "fy" | "batch";
export type ExportFormat = "excel" | "pdf" | "form8" | "form4";

const CATEGORIES = [
  { value: "hazardous", label: "Hazardous" },
  { value: "non_hazardous", label: "Non-Hazardous" },
  { value: "e_waste", label: "E-Waste" },
  { value: "other_wastes", label: "Other Wastes" },
] as const;

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** "excel", "pdf" or "form8" — pre-selected based on which button was clicked */
  initialFormat: ExportFormat;
  siteName: string;
  entries: WasteEntry[];
  batches: DisposalBatch[];
  onExport: (opts: {
    format: ExportFormat;
    filteredEntries: WasteEntry[];
    chosenBatch: DisposalBatch | null;
    periodLabel: string;
    selectedFy: number;
    form8Mode?: "summary" | "per_entry";
  }) => void;
}

export default function ExportOptionsDialog({
  open,
  onOpenChange,
  initialFormat,
  siteName,
  entries,
  batches,
  onExport,
}: Props) {
  const [formatType, setFormatType] = useState<ExportFormat>(initialFormat);
  const [periodKind, setPeriodKind] = useState<PeriodKind>("all");
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth());
  const [rangeStart, setRangeStart] = useState("");
  const [rangeEnd, setRangeEnd] = useState("");
  const [selectedFy, setSelectedFy] = useState<number>(
    new Date().getMonth() >= 3 ? new Date().getFullYear() : new Date().getFullYear() - 1
  );
  const [batchId, setBatchId] = useState<string>("");
  const [categories, setCategories] = useState<string[]>([]);
  const [wasteTypeIds, setWasteTypeIds] = useState<string[]>([]);
  const [form8Mode, setForm8Mode] = useState<"summary" | "per_entry">("summary");

  // Calendar popover open states
  const [rangeStartOpen, setRangeStartOpen] = useState(false);
  const [rangeEndOpen, setRangeEndOpen] = useState(false);

  useEffect(() => {
    if (open) {
      setFormatType(initialFormat);
      setPeriodKind(initialFormat === "form4" ? "fy" : "all");
      setCategories([]);
      setWasteTypeIds([]);
      setRangeStart("");
      setRangeEnd("");
      setBatchId("");
      setRangeStartOpen(false);
      setRangeEndOpen(false);
      setForm8Mode("summary");
    }
  }, [open, initialFormat]);

  const years = useMemo(() => {
    const cur = new Date().getFullYear();
    return Array.from({ length: cur - 2019 }, (_, i) => 2020 + i);
  }, []);

  const monthLabels = [
    "Jan",
    "Feb",
    "Mar",
    "Apr",
    "May",
    "Jun",
    "Jul",
    "Aug",
    "Sep",
    "Oct",
    "Nov",
    "Dec",
  ];

  // ── Cascading waste types based on selected categories ─────────
  const filteredWasteTypes = useMemo(() => {
    if (categories.length === 0) return WASTE_TYPES;
    return WASTE_TYPES.filter((w) => categories.includes(w.wasteCategory));
  }, [categories]);

  // Reset waste type selection if types are no longer in scope
  useEffect(() => {
    if (wasteTypeIds.length > 0) {
      const valid = wasteTypeIds.filter((id) => filteredWasteTypes.find((w) => w.id === id));
      if (valid.length !== wasteTypeIds.length) setWasteTypeIds(valid);
    }
  }, [categories, filteredWasteTypes]);

  // ── Compute filtered entries ──────────────────────────────────
  const filteredEntries = useMemo(() => {
    let list = entries;

    // Period
    if (periodKind === "month") {
      list = list.filter((e) => {
        const d = new Date(e.generated_date);
        return d.getFullYear() === selectedYear && d.getMonth() === selectedMonth;
      });
    } else if (periodKind === "range" && rangeStart && rangeEnd) {
      const s = new Date(rangeStart + "T00:00:00").getTime();
      const e = new Date(rangeEnd + "T23:59:59").getTime();
      list = list.filter((x) => {
        const t = new Date(x.generated_date + "T00:00:00").getTime();
        return t >= s && t <= e;
      });
    } else if (periodKind === "fy") {
      const fyStart = `${selectedFy}-04-01`;
      const fyEnd = `${selectedFy + 1}-03-31`;
      const s = new Date(fyStart + "T00:00:00").getTime();
      const e = new Date(fyEnd + "T23:59:59").getTime();
      list = list.filter((x) => {
        const t = new Date(x.generated_date + "T00:00:00").getTime();
        return t >= s && t <= e;
      });
    } else if (periodKind === "batch" && batchId) {
      list = list.filter((x) => x.disposal_batch_id === batchId);
    }

    // Category (multi)
    if (categories.length > 0) {
      list = list.filter((e) => categories.includes(e.waste_category));
    }

    // Waste type (multi)
    if (wasteTypeIds.length > 0) {
      list = list.filter((e) => wasteTypeIds.includes(e.waste_type_id));
    }

    return list;
  }, [
    entries,
    periodKind,
    selectedYear,
    selectedMonth,
    rangeStart,
    rangeEnd,
    selectedFy,
    batchId,
    categories,
    wasteTypeIds,
  ]);

  const chosenBatch =
    periodKind === "batch" && batchId ? batches.find((b) => b.id === batchId) ?? null : null;

  const periodLabel = useMemo(() => {
    if (periodKind === "all") return "All Time";
    if (periodKind === "month") return `${monthLabels[selectedMonth]} ${selectedYear}`;
    if (periodKind === "range" && rangeStart && rangeEnd) return `${formatDateDDMMYYYY(rangeStart)} → ${formatDateDDMMYYYY(rangeEnd)}`;
    if (periodKind === "fy") return `FY ${selectedFy}-${String(selectedFy + 1).slice(-2)}`;
    if (periodKind === "batch" && chosenBatch) return `Batch ${formatDateDDMMYYYY(chosenBatch.disposed_date)}`;
    return "All Time";
  }, [periodKind, selectedYear, selectedMonth, rangeStart, rangeEnd, selectedFy, batchId, chosenBatch]);

  const totals = useMemo(() => {
    let kg = 0,
      litres = 0,
      count = 0;
    for (const e of filteredEntries) {
      const w = Number(e.weight_kg ?? 0);
      const u = getMeasureUnit(e.waste_type_id);
      if (u === "litres") litres += w;
      else kg += w;
      count += 1;
    }
    return { kg, litres, count };
  }, [filteredEntries]);

  const approvedBatches = batches.filter((b) => b.status === "approved" || !b.status);

  const handleExport = () => {
    onExport({ format: formatType, filteredEntries, chosenBatch, periodLabel, selectedFy, form8Mode });
    onOpenChange(false);
  };

  const fmtDate = (s: string) => (s ? formatDateDDMMYYYY(s) : "");

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto rounded-xl">
        <DialogHeader>
          <DialogTitle className="text-base font-semibold flex items-center gap-2">
            <Download className="h-4 w-4 text-primary" />
            Export Compliance Records
          </DialogTitle>
          <DialogDescription className="text-xs">
            Generate statutory reports or spreadsheets for facility: <strong className="text-foreground">{siteName}</strong>
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-3.5 py-1">
          {/* ── Format selection ── */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">Report Format</Label>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
              <button
                type="button"
                onClick={() => setFormatType("excel")}
                className={`flex flex-col items-center justify-center text-center p-2 rounded-lg border text-xs transition-all ${
                  formatType === "excel"
                    ? "border-primary bg-primary/10 text-primary font-semibold ring-1 ring-primary/20"
                    : "border-border hover:bg-muted/70 text-muted-foreground"
                }`}
              >
                <FileSpreadsheet className="h-4 w-4 text-emerald-600 mb-1" />
                <span className="font-semibold text-foreground text-[11px]">Excel (.xlsx)</span>
                <span className="text-[10px] text-muted-foreground">Full data register</span>
              </button>
              <button
                type="button"
                onClick={() => setFormatType("pdf")}
                className={`flex flex-col items-center justify-center text-center p-2 rounded-lg border text-xs transition-all ${
                  formatType === "pdf"
                    ? "border-primary bg-primary/10 text-primary font-semibold ring-1 ring-primary/20"
                    : "border-border hover:bg-muted/70 text-muted-foreground"
                }`}
              >
                <FileText className="h-4 w-4 text-rose-600 mb-1" />
                <span className="font-semibold text-foreground text-[11px]">Form 3 PDF</span>
                <span className="text-[10px] text-muted-foreground">HOWM Passbook</span>
              </button>
              <button
                type="button"
                onClick={() => setFormatType("form8")}
                className={`flex flex-col items-center justify-center text-center p-2 rounded-lg border text-xs transition-all ${
                  formatType === "form8"
                    ? "border-primary bg-primary/10 text-primary font-semibold ring-1 ring-primary/20"
                    : "border-border hover:bg-muted/70 text-muted-foreground"
                }`}
              >
                <Tag className="h-4 w-4 text-amber-600 mb-1" />
                <span className="font-semibold text-foreground text-[11px]">Form 8 Labels</span>
                <span className="text-[10px] text-muted-foreground">Rule 17 Drum Signs</span>
              </button>
              <button
                type="button"
                onClick={() => {
                  setFormatType("form4");
                  setPeriodKind("fy");
                }}
                className={`flex flex-col items-center justify-center text-center p-2 rounded-lg border text-xs transition-all ${
                  formatType === "form4"
                    ? "border-primary bg-primary/10 text-primary font-semibold ring-1 ring-primary/20"
                    : "border-border hover:bg-muted/70 text-muted-foreground"
                }`}
              >
                <FileCheck className="h-4 w-4 text-blue-600 mb-1" />
                <span className="font-semibold text-foreground text-[11px]">Form 4 Return</span>
                <span className="text-[10px] text-muted-foreground">Rule 20(2) Annual</span>
              </button>
            </div>
          </div>

          {/* ── Form 8 Label Mode ── */}
          {formatType === "form8" && (
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Label Mode</Label>
              <div className="grid grid-cols-2 gap-2">
                <button
                  type="button"
                  onClick={() => setForm8Mode("summary")}
                  className={`p-2.5 rounded-lg border text-left transition-all ${
                    form8Mode === "summary"
                      ? "border-primary bg-primary/10 text-primary font-semibold ring-1 ring-primary/20"
                      : "border-border hover:bg-muted/70 text-muted-foreground"
                  }`}
                >
                  <div className="font-semibold text-foreground text-xs">Summary by Waste Type</div>
                  <div className="text-[10px] text-muted-foreground mt-0.5">
                    One label per waste type with total quantity
                  </div>
                </button>

                <button
                  type="button"
                  onClick={() => setForm8Mode("per_entry")}
                  className={`p-2.5 rounded-lg border text-left transition-all ${
                    form8Mode === "per_entry"
                      ? "border-primary bg-primary/10 text-primary font-semibold ring-1 ring-primary/20"
                      : "border-border hover:bg-muted/70 text-muted-foreground"
                  }`}
                >
                  <div className="font-semibold text-foreground text-xs">Per Entry (Individual)</div>
                  <div className="text-[10px] text-muted-foreground mt-0.5">
                    One label per drum / log entry
                  </div>
                </button>
              </div>
            </div>
          )}

          {/* ── Period ── */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">Reporting Period</Label>
            <Select value={periodKind} onValueChange={(v) => setPeriodKind(v as PeriodKind)}>
              <SelectTrigger className="h-9 text-xs rounded-lg">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Time</SelectItem>
                <SelectItem value="month">Specific Month</SelectItem>
                <SelectItem value="range">Custom Date Range</SelectItem>
                <SelectItem value="fy">Financial Year</SelectItem>
                <SelectItem value="batch">Specific Disposal Batch</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {periodKind === "month" && (
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">Year</Label>
                <Select value={String(selectedYear)} onValueChange={(v) => setSelectedYear(Number(v))}>
                  <SelectTrigger className="h-9 text-xs rounded-lg">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {years.map((y) => (
                      <SelectItem key={y} value={String(y)}>
                        {y}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">Month</Label>
                <Select value={String(selectedMonth)} onValueChange={(v) => setSelectedMonth(Number(v))}>
                  <SelectTrigger className="h-9 text-xs rounded-lg">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {monthLabels.map((m, i) => (
                      <SelectItem key={i} value={String(i)}>
                        {m}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          )}

          {periodKind === "range" && (
            <div className="grid grid-cols-2 gap-2">
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">From</Label>
                <Popover open={rangeStartOpen} onOpenChange={setRangeStartOpen}>
                  <PopoverTrigger asChild>
                    <Button variant="outline" className="w-full justify-start text-left font-normal h-9 text-xs rounded-lg">
                      <CalendarIcon className="mr-2 h-3.5 w-3.5 text-muted-foreground" />
                      {rangeStart ? fmtDate(rangeStart) : "Pick date"}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={rangeStart ? new Date(rangeStart + "T00:00:00") : undefined}
                      onSelect={(d) => {
                        if (d) {
                          setRangeStart(format(d, "yyyy-MM-dd"));
                        }
                        setRangeStartOpen(false);
                      }}
                    />
                  </PopoverContent>
                </Popover>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs font-semibold">To</Label>
                <Popover open={rangeEndOpen} onOpenChange={setRangeEndOpen}>
                  <PopoverTrigger asChild>
                    <Button variant="outline" className="w-full justify-start text-left font-normal h-9 text-xs rounded-lg">
                      <CalendarIcon className="mr-2 h-3.5 w-3.5 text-muted-foreground" />
                      {rangeEnd ? fmtDate(rangeEnd) : "Pick date"}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0" align="start">
                    <Calendar
                      mode="single"
                      selected={rangeEnd ? new Date(rangeEnd + "T00:00:00") : undefined}
                      onSelect={(d) => {
                        if (d) {
                          setRangeEnd(format(d, "yyyy-MM-dd"));
                        }
                        setRangeEndOpen(false);
                      }}
                    />
                  </PopoverContent>
                </Popover>
              </div>
            </div>
          )}

          {periodKind === "fy" && (
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Financial Year</Label>
              <Select value={String(selectedFy)} onValueChange={(v) => setSelectedFy(Number(v))}>
                <SelectTrigger className="h-9 text-xs rounded-lg">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {years.map((y) => (
                    <SelectItem key={y} value={String(y)}>
                      FY {y}-{String(y + 1).slice(-2)}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {periodKind === "batch" && (
            <div className="space-y-1.5">
              <Label className="text-xs font-semibold">Disposal Batch</Label>
              {approvedBatches.length === 0 ? (
                <p className="text-xs text-muted-foreground italic">No approved disposal batches yet.</p>
              ) : (
                <Select value={batchId} onValueChange={setBatchId}>
                  <SelectTrigger className="h-9 text-xs rounded-lg">
                    <SelectValue placeholder="Pick a batch" />
                  </SelectTrigger>
                  <SelectContent>
                    {approvedBatches.map((b) => (
                      <SelectItem key={b.id} value={b.id}>
                        {b.disposed_date} {b.notes ? ` — ${b.notes.slice(0, 30)}` : ""}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>
          )}

          {/* ── Category filter (multi) ── */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">Filter by Category</Label>
            <MultiSelect
              options={CATEGORIES.map((c) => ({ value: c.value, label: c.label }))}
              value={categories}
              onChange={setCategories}
              placeholder="All categories"
            />
          </div>

          {/* ── Waste type filter (multi, cascades from category) ── */}
          <div className="space-y-1.5">
            <Label className="text-xs font-semibold">Filter by Waste Type</Label>
            <MultiSelect
              options={filteredWasteTypes.map((w) => ({ value: w.id, label: w.name }))}
              value={wasteTypeIds}
              onChange={setWasteTypeIds}
              placeholder={categories.length > 0 ? "All types in selected categories" : "All waste types"}
            />
          </div>

          {/* ── Preview summary card ── */}
          <div className="rounded-xl border border-border/80 bg-muted/40 p-3 space-y-1.5 text-xs shadow-xs">
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">Scope:</span>
              <Badge variant="outline" className="text-[10px] font-medium">
                {periodLabel}
              </Badge>
            </div>
            <div className="flex items-center justify-between">
              <span className="text-muted-foreground">Matching Records:</span>
              <span className="font-mono font-semibold text-foreground">{totals.count} entries</span>
            </div>
            {formatType === "form8" && form8Mode === "summary" && (
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground">Waste Types:</span>
                <span className="font-mono font-semibold text-foreground">
                  {new Set(filteredEntries.map((e) => e.waste_type_id)).size} unique labels
                </span>
              </div>
            )}
            {totals.kg > 0 && (
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground">Total Weight:</span>
                <span className="font-mono font-semibold text-foreground">{fmtNum(totals.kg)} kg</span>
              </div>
            )}
            {totals.litres > 0 && (
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground">Total Volume:</span>
                <span className="font-mono font-semibold text-foreground">{fmtNum(totals.litres)} L</span>
              </div>
            )}
          </div>
        </div>

        <DialogFooter className="gap-2 pt-2">
          <DialogClose asChild>
            <Button variant="outline" size="sm" className="h-9 text-xs">
              Cancel
            </Button>
          </DialogClose>
          <Button
            size="sm"
            disabled={
              formatType === "form4"
                ? false
                : filteredEntries.length === 0 || (periodKind === "batch" && !batchId)
            }
            onClick={handleExport}
            className="h-9 text-xs bg-primary hover:bg-primary/90 text-primary-foreground font-semibold"
          >
            {formatType === "excel" ? (
              <FileSpreadsheet className="h-4 w-4 mr-1.5" />
            ) : formatType === "pdf" ? (
              <FileText className="h-4 w-4 mr-1.5" />
            ) : formatType === "form8" ? (
              <Tag className="h-4 w-4 mr-1.5" />
            ) : (
              <FileCheck className="h-4 w-4 mr-1.5" />
            )}
            Generate{" "}
            {formatType === "excel"
              ? "Excel"
              : formatType === "pdf"
              ? "Form 3 PDF"
              : formatType === "form8"
              ? "Form 8 Labels"
              : "Form 4 Return"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { csvCell as sanitizeCsv } from "@/lib/csv";
import { useEffect, useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  Settings,
  Download,
  LogOut,
  Building2,
  Shield,
  FileSpreadsheet,
  CheckCircle2,
  Info,
  User,
  Users,
  ChevronRight,
  ShieldCheck,
} from "lucide-react";
import { WasteEntry, WASTE_TYPES, formatDateDDMMYYYY } from "@/lib/wasteTypes";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useAuth } from "@/contexts/AuthContext";
import { useSite } from "@/contexts/SiteContext";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import EmptyState from "@/components/ui/empty-state";

interface Props {
  entries: WasteEntry[];
  onNavigateToAdmin?: (subTab?: "users" | "sites" | "records" | "audit") => void;
}

interface SiteMember {
  user_id: string;
  email: string | null;
  full_name: string | null;
  roles: string[];
}

export default function SettingsTab({ entries, onNavigateToAdmin }: Props) {
  const { user, signOut } = useAuth();
  const { currentSite, isAdmin, sites, setCurrentSite } = useSite();
  const [members, setMembers] = useState<SiteMember[]>([]);

  const loadMembers = async () => {
    if (!currentSite?.id) return;
    try {
      const [{ data: ms }, { data: rs }] = await Promise.all([
        supabase.from("user_sites").select("user_id").eq("site_id", currentSite.id),
        supabase.from("user_roles").select("user_id, role").eq("site_id", currentSite.id),
      ]);
      const userIds = Array.from(
        new Set([...(ms ?? []).map((m) => m.user_id), ...(rs ?? []).map((r) => r.user_id)])
      );
      const profMap: Record<string, { email: string | null; full_name: string | null }> = {};
      if (userIds.length > 0) {
        const { data: ps } = await supabase.from("profiles").select("id, email, full_name").in("id", userIds);
        (ps ?? []).forEach((p) => {
          profMap[p.id] = { email: p.email, full_name: p.full_name };
        });
      }
      const rolesByUser: Record<string, string[]> = {};
      (rs ?? []).forEach((r) => {
        rolesByUser[r.user_id] = [...(rolesByUser[r.user_id] ?? []), r.role];
      });
      setMembers(
        userIds.map((uid) => ({
          user_id: uid,
          email: profMap[uid]?.email ?? null,
          full_name: profMap[uid]?.full_name ?? null,
          roles: rolesByUser[uid] ?? [],
        }))
      );
    } catch (err) {
      console.error("Failed to load facility members:", err);
    }
  };

  useEffect(() => {
    loadMembers();
  }, [currentSite?.id]);


  const handleExport = () => {
    const csv = [
      "Facility,Location,Waste Type,Category,Weight,Unit,Count (pcs),Activity,Generated,Disposed Batch,Notes",
      ...entries.map((e) => {
        const wt = WASTE_TYPES.find((w) => w.id === e.waste_type_id);
        const unit = wt?.measureUnit === "litres" ? "Ltr" : "kg";
        return [
          sanitizeCsv(sites.find(s => s.id === e.site_id)?.name ?? e.site_id),
          sanitizeCsv(e.location),
          sanitizeCsv(wt?.name ?? e.waste_type_id),
          sanitizeCsv(e.waste_category),
          sanitizeCsv(e.weight_kg ?? ""),
          sanitizeCsv(unit),
          sanitizeCsv(e.piece_count ?? ""),
          sanitizeCsv(e.activity_type),
          sanitizeCsv(formatDateDDMMYYYY(e.generated_date)),
          sanitizeCsv(e.disposal_batch_id ?? ""),
          sanitizeCsv(e.notes ?? ""),
        ].join(",");
      }),
    ].join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `waste-${currentSite?.name ?? "facility"}-${new Date().toISOString().split("T")[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success("CSV dataset exported successfully");
  };

  const initial = user?.email?.charAt(0).toUpperCase() ?? "U";

  return (
    <div className="w-full space-y-3.5 sm:space-y-4 lg:space-y-5">
      {/* ── User Profile & Facility Header Banner ── */}
      <Card className="border-border/80 shadow-xs overflow-hidden">
        <CardContent className="p-3.5 sm:p-5">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="flex items-center gap-2.5 sm:gap-3">
              <div className="h-9.5 w-9.5 sm:h-11 sm:w-11 rounded-xl sm:rounded-2xl bg-primary/10 text-primary font-bold text-base sm:text-lg flex items-center justify-center shrink-0 border border-primary/20">
                {initial}
              </div>
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <h3 className="text-sm font-bold text-foreground truncate">{user?.email}</h3>
                  {isAdmin && (
                    <Badge variant="default" className="text-[10px] uppercase font-mono">
                      Admin
                    </Badge>
                  )}
                </div>
                {currentSite && (
                  <p className="text-xs text-muted-foreground mt-0.5 flex items-center gap-1.5">
                    <Building2 className="h-3.5 w-3.5 text-primary" />
                    <span>Active: </span>
                    <strong className="text-foreground">{currentSite.name}</strong>
                    {currentSite.location && <span className="text-[11px] font-mono">({currentSite.location})</span>}
                  </p>
                )}
              </div>
            </div>

            <Button
              variant="outline"
              size="sm"
              className="h-8 text-xs gap-1.5 text-destructive hover:bg-destructive/10 rounded-lg self-start sm:self-auto shrink-0"
              onClick={signOut}
            >
              <LogOut className="h-3.5 w-3.5" />
              <span>Sign out</span>
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* ── Admin Portal Access Card (Mobile & Desktop) ── */}
      {isAdmin && onNavigateToAdmin && (
        <Card className="border-primary/40 bg-primary/5 shadow-xs overflow-hidden">
          <CardContent className="p-3.5 sm:p-5 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="flex items-center gap-2.5 sm:gap-3">
              <div className="h-9 w-9 sm:h-10 sm:w-10 rounded-lg sm:rounded-xl bg-primary text-primary-foreground flex items-center justify-center shrink-0 shadow-xs">
                <ShieldCheck className="h-4.5 w-4.5 sm:h-5 sm:w-5" />
              </div>
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <h3 className="text-sm font-bold text-foreground">Enterprise Administration</h3>
                  <Badge variant="default" className="text-[9px] uppercase font-mono bg-primary">
                    Admin
                  </Badge>
                </div>
                <p className="text-xs text-muted-foreground mt-0.5">
                  Manage user accounts, roles, site permissions, and disposal batch approvals.
                </p>
              </div>
            </div>

            <Button
              onClick={() => onNavigateToAdmin()}
              size="sm"
              className="gap-2 bg-primary hover:bg-primary/90 text-primary-foreground font-semibold shadow-xs rounded-lg shrink-0 self-stretch sm:self-auto"
            >
              <Shield className="h-4 w-4" />
              <span>Open Admin Portal</span>
              <ChevronRight className="h-4 w-4" />
            </Button>
          </CardContent>
        </Card>
      )}

      {/* ── Grouped Sections 1 & 2: Facilities & Team (Adaptive 2-column layout on desktop) ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-3 sm:gap-4 lg:gap-5">
        {/* Section 1: Facility Sites & Workspaces */}
        <Card className={cn("border-border/80 shadow-xs flex flex-col justify-between", !currentSite && "lg:col-span-2")}>
          <CardContent className="p-3.5 sm:p-4 space-y-2.5 sm:space-y-3">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Building2 className="h-4 w-4 text-primary" />
                <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                  Authorized Facilities ({sites.length})
                </h3>
              </div>
              {isAdmin && onNavigateToAdmin && (
                <Button
                  variant="outline"
                  size="sm"
                  className="h-7 text-xs gap-1.5 px-2.5 rounded-lg shadow-2xs font-medium text-foreground hover:bg-muted"
                  onClick={() => onNavigateToAdmin("sites")}
                >
                  <ShieldCheck className="h-3.5 w-3.5 text-primary" />
                  <span>Manage in Admin</span>
                </Button>
              )}
            </div>

            {/* Site List */}
            <div className="divide-y divide-border/60 text-xs rounded-lg border border-border/60 overflow-hidden bg-background">
              {sites.map((s) => {
                const isActive = s.id === currentSite?.id;
                return (
                  <div
                    key={s.id}
                    className={cn(
                      "p-2.5 sm:p-3 flex items-center justify-between gap-2 transition-colors cursor-pointer",
                      isActive ? "bg-primary/5" : "hover:bg-muted/40"
                    )}
                    onClick={() => setCurrentSite({ id: s.id, name: s.name, location: s.location })}
                  >
                    <div className="flex items-center gap-2.5 min-w-0">
                      <div
                        className={cn(
                          "h-2 w-2 rounded-full shrink-0",
                          isActive ? "bg-emerald-600 ring-2 ring-emerald-600/30" : "bg-muted-foreground/30"
                        )}
                      />
                      <span className={cn("truncate", isActive ? "font-bold text-foreground" : "text-muted-foreground")}>
                        {s.name}
                      </span>
                      {isActive && (
                        <span className="text-[10px] font-semibold text-emerald-700 dark:text-emerald-400 bg-emerald-500/10 px-1.5 py-0.2 rounded">
                          Active
                        </span>
                      )}
                    </div>
                    {s.location && (
                      <span className="text-[11px] text-muted-foreground font-mono shrink-0">
                        {s.location}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          </CardContent>
        </Card>

        {/* Section 2: Facility Team Roster */}
        {currentSite && (
          <Card className="border-border/80 shadow-xs flex flex-col justify-between">
            <CardContent className="p-3.5 sm:p-4 space-y-2.5 sm:space-y-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Users className="h-4 w-4 text-primary" />
                  <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground truncate">
                    <span>Operators on {currentSite.name} ({members.length})</span>
                  </h3>
                </div>
                {isAdmin && onNavigateToAdmin && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-7 text-xs gap-1.5 px-2.5 rounded-lg shadow-2xs font-medium text-foreground hover:bg-muted"
                    onClick={() => onNavigateToAdmin("users")}
                  >
                    <ShieldCheck className="h-3.5 w-3.5 text-primary" />
                    <span>Manage Users</span>
                  </Button>
                )}
              </div>

              {/* Member List */}
              {members.length === 0 ? (
                <EmptyState
                  key="empty-members"
                  icon={Users}
                  title="No Members Assigned"
                  description="No operator accounts are assigned to this facility."
                  compact
                />
              ) : (
                <div key="members-list" className="divide-y divide-border/60 text-xs rounded-lg border border-border/60 overflow-hidden bg-background">
                  {members.map((m) => (
                    <div key={m.user_id} className="p-2.5 flex justify-between items-center gap-2">
                      <div className="flex items-center gap-2 min-w-0">
                        <div className="h-6 w-6 rounded-full bg-muted flex items-center justify-center text-[10px] font-bold text-muted-foreground shrink-0">
                          <span>{m.email?.charAt(0).toUpperCase() ?? "U"}</span>
                        </div>
                        <p className="truncate font-medium text-foreground">{m.email ?? m.full_name}</p>
                      </div>
                      <span className="text-muted-foreground shrink-0 capitalize text-[10px] font-mono bg-muted/80 px-2 py-0.5 rounded border border-border/50">
                        {m.roles.join(", ") || "member"}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        )}
      </div>

      {/* ── Grouped Sections 3 & 4: Data Management & Regulatory Info (Adaptive 2-column layout on desktop) ── */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-3 sm:gap-4 lg:gap-5">
        {/* Section 3: Data Management */}
        <Card className="border-border/80 shadow-xs flex flex-col justify-between">
          <CardContent className="p-3.5 sm:p-4 space-y-2.5 sm:space-y-3">
            <div className="flex items-center gap-2">
              <Download className="h-4 w-4 text-primary" />
              <h3 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
